// Heure/date correctes pour le Maroc (Africa/Casablanca), au lieu de l'UTC brut
// qui affichait toujours 1h de moins.
function moroccoNow() {
  const OFFSET_HOURS = 1; // Maroc = UTC+1 en permanence (sauf periode Ramadan = UTC+0)
  const local = new Date(Date.now() + OFFSET_HOURS * 60 * 60 * 1000);
  const pad = (n) => String(n).padStart(2, "0");
  const date = `${local.getUTCFullYear()}-${pad(local.getUTCMonth() + 1)}-${pad(local.getUTCDate())}`;
  const datetime = `${date}T${pad(local.getUTCHours())}:${pad(local.getUTCMinutes())}:${pad(local.getUTCSeconds())}+01:00`;
  return { date, datetime };
}
const now = moroccoNow();

// Bloquer un 2e (ou 3e...) scan le meme jour pour le meme etudiant
const todaysAttendance = (outputs["Postgres Action5"] && outputs["Postgres Action5"].success.rows) || [];
const alreadyCheckedIn = todaysAttendance.some(
  (r) => String(r.student_id) === String(student.id)
);
if (alreadyCheckedIn) {
  throw new Error(`Etudiant ${student.id} deja enregistre aujourd'hui (${now.date})`);
}

return {
  student_id: String(student.id),
  rfid_uid: String(mqttData.rfid_uid),
  event_type: "check_in",
  scanned_at: now.datetime,
  attendance_date: now.date,
  raw_payload: mqttData
};

try {
  const result = outputs["Postgres Action3"].success;
  const rows = result.rows || [];

  if (rows.length === 0) {
    return {
      success: true,
      should_notify: false,
      alerts_count: 0,
      alertsData: [],
      alertsRows: [],
      subject: "",
      message: "",
      error: ""
    };
  }

  const date = new Date().toISOString().split("T")[0];

  const lines = rows.map((student, index) => {
    return `${index + 1}. ${student.first_name} ${student.last_name} (${student.student_code})`;
  });

  const message =
    `Bonjour,\n\n` +
    `Voici la liste des étudiants absents le ${date} :\n\n` +
    lines.join("\n") +
    `\n\nNombre total d'étudiants absents : ${rows.length}`;

  const alertsRows = rows.map(student => ({
    student_id: student.student_id,
    alert_type: "absence",
    alert_date: date,
    message: `Absence détectée : ${student.first_name} ${student.last_name} (${student.student_code})`,
    status: "pending"
  }));

  return {
    success: true,
    should_notify: true,
    alerts_count: rows.length,
    alertsData: rows,
    alertsRows: alertsRows,
    subject: `Absences - ${date}`,
    message: message,
    error: ""
  };

} catch (e) {
  return {
    success: false,
    should_notify: false,
    alerts_count: 0,
    alertsData: [],
    alertsRows: [],
    subject: "",
    message: "",
    error: String(e)
  };
}

const pg = outputs["Postgres Action3"].success;
const rows = pg.rows || [];

if (rows.length === 0) {
  // Rien à insérer : on sort par la branche "error" (non connectée à Postgres Action4)
  // pour ne pas créer d'alerte vide quand il n'y a aucun absent.
  throw new Error("Aucun élève absent aujourd'hui - rien à insérer dans alerts");
