  const total = Number(counts.total_students) || 0;
  const presents = Number(counts.presents) || 0;
  const absents = Number(counts.absents) || 0;
  const rate = total > 0 ? Math.round((presents / total) * 1000) / 10 : 0;

  const date = new Date().toISOString().split("T")[0];

  return {
    success: true,
    payload: {
      date: date,
      total_students: total,
      presents: presents,
      absents: absents,
      presence_rate: rate,
      alerts_sent: absents
    },
    rows: [[date, total, presents, absents, rate, absents]]
  };
} catch (e) {
  return { success: false, error: String(e) };
