const contenu = outputs.Function12.success.contenu;
const documentId = input.documentId;

function utf8ToBase64(str) {
  const utf8Bytes = [];
  for (let i = 0; i < str.length; i++) {
    let charcode = str.charCodeAt(i);
    if (charcode < 0x80) {
      utf8Bytes.push(charcode);
    } else if (charcode < 0x800) {
      utf8Bytes.push(0xc0 | (charcode >> 6), 0x80 | (charcode & 0x3f));
    } else if (charcode < 0xd800 || charcode >= 0xe000) {
      utf8Bytes.push(
        0xe0 | (charcode >> 12),
        0x80 | ((charcode >> 6) & 0x3f),
        0x80 | (charcode & 0x3f)
      );
    } else {
      // surrogate pair
      i++;
      charcode = 0x10000 + (((charcode & 0x3ff) << 10) | (str.charCodeAt(i) & 0x3ff));
      utf8Bytes.push(
        0xf0 | (charcode >> 18),
        0x80 | ((charcode >> 12) & 0x3f),
        0x80 | ((charcode >> 6) & 0x3f),
        0x80 | (charcode & 0x3f)
      );
    }
  }

  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let result = '';
  for (let i = 0; i < utf8Bytes.length; i += 3) {
    const b1 = utf8Bytes[i];
    const b2 = i + 1 < utf8Bytes.length ? utf8Bytes[i + 1] : NaN;
    const b3 = i + 2 < utf8Bytes.length ? utf8Bytes[i + 2] : NaN;

    result += chars[b1 >> 2];
    result += chars[((b1 & 3) << 4) | (isNaN(b2) ? 0 : (b2 >> 4))];
    result += isNaN(b2) ? '=' : chars[((b2 & 15) << 2) | (isNaN(b3) ? 0 : (b3 >> 6))];
    result += isNaN(b3) ? '=' : chars[b3 & 63];
  }
  return result;
}

const contentBase64 = utf8ToBase64(contenu);

return {
  documentId: documentId,
  contentBase64: contentBase64
};
